const prompts={bn:['আপনার নাম বলুন।','আপনার ফ্ল্যাট নম্বর বলুন।','পানির কী সমস্যা হয়েছে? যেমন পানি আসছে না, চাপ কম, লিকেজ, অথবা অন্য সমস্যা।','সমস্যাটি কখন থেকে হচ্ছে এবং কী ঘটেছে, একটু বিস্তারিত বলুন।','এটি কি জরুরি সমস্যা? হ্যাঁ অথবা না বলুন।','আপনার ফোন নম্বরটি বলুন, যাতে প্রয়োজনে কর্মীরা যোগাযোগ করতে পারেন।','আপনার অভিযোগের সারাংশ: {summary}। অভিযোগটি জমা দেব? হ্যাঁ অথবা না বলুন।'],en:['Please say your name.','Please say your flat number.','What is the water problem? Say no water, low pressure, leak, or another problem.','Please describe what happened and when it started.','Is this urgent? Please say yes or no.','Please say your phone number so staff can contact you if needed.','Here is your report: {summary}. Should I submit it? Say yes or no.']};
function sayVoice(text,afterSpeak){const synth=window.speechSynthesis;if(!synth){voiceSpeechFailed=true;showVoiceTyping('Speech playback is unavailable in this browser.');afterSpeak?.();return}const voices=synth.getVoices(),speech=new SpeechSynthesisUtterance(text),wanted=['en-us','en-gb','en-in','en-au','en-ca'];speech.lang='en-US';speech.voice=voices.find(v=>wanted.includes(v.lang.toLowerCase()))||voices.find(v=>v.default)||null;speech.rate=.92;speech.volume=1;speech.onstart=()=>{document.querySelector('#voiceFeedback').textContent='Assistant is speaking…'};speech.onend=()=>{document.querySelector('#voiceFeedback').textContent='';afterSpeak?.()};speech.onerror=e=>{if(e.error==='canceled'||e.error==='interrupted')return;voiceSpeechFailed=true;document.querySelector('#voiceFeedback').textContent='Could not play speech. Check the device voice settings.';afterSpeak?.()};synth.resume();synth.speak(speech)}
function listenAutomatically(){if(voiceSpeechFailed){showVoiceTyping('Speech playback failed.');return}if(!recognition||!micReady)return;try{recognition.start()}catch(error){micReady=false;showVoiceTyping('Could not start the microphone. Check permission or type your answer.')}}
function stopVoiceStream(){voiceStream?.getTracks().forEach(track=>track.stop());voiceStream=null}
function showVoiceTyping(message){micReady=false;stopVoiceStream();document.querySelector('#voiceFeedback').textContent=message;document.querySelector('#voiceListen').hidden=true;document.querySelector('#voiceText').hidden=false;document.querySelector('#voiceSend').hidden=false;document.querySelector('#voiceStart').hidden=false}
function voiceQuestion(){const spokenType=voiceLanguage==='bn'?voiceData.type:(english[voiceData.type]||voiceData.type),prompt=(prompts[voiceLanguage][voiceStep]||'').replace('{summary}',`${voiceData.name}, ${voiceData.flat}, ${spokenType}, ${voiceData.details}, ${voiceData.urgent?(voiceLanguage==='bn'?'জরুরি':'urgent'):(voiceLanguage==='bn'?'জরুরি নয়':'not urgent')}, ${voiceData.phone}`);document.querySelector('#voicePrompt').textContent=prompt;document.querySelector('#voiceProgress').textContent=`${voiceLanguage==='bn'?'প্রশ্ন':'Question'} ${Math.min(voiceStep+1,7)} / 7`;document.querySelector('#voiceListen').hidden=true;document.querySelector('#voiceText').hidden=micReady;document.querySelector('#voiceSend').hidden=micReady;sayVoice(prompt,listenAutomatically)}
function acceptVoiceAnswer(raw){
  const answer=raw.trim();
  if(!answer){voiceAttempts++;document.querySelector('#voiceFeedback').textContent=voiceLanguage==='bn'?'উত্তরটি শুনতে পাইনি। আবার বলুন।':'I did not catch that. Please try again.';voiceQuestion();return}
  voiceAttempts=0;document.querySelector('#voiceFeedback').textContent='';
  if(voiceStep===0)voiceData.name=answer;
  else if(voiceStep===1)voiceData.flat=answer;
  else if(voiceStep===2){voiceData.issue=answer;const lower=answer.toLocaleLowerCase();let matched='';if(voiceLanguage==='bn')matched=['পানি আসছে না','পানির চাপ কম','পাইপে লিকেজ','নোংরা বা দুর্গন্ধযুক্ত পানি'].find(x=>lower.includes(x))||'';else{const m=[['no water','পানি আসছে না'],['low water pressure','পানির চাপ কম'],['leak','পাইপে লিকেজ'],['dirty water','নোংরা বা দুর্গন্ধযুক্ত পানি'],['smelly water','নোংরা বা দুর্গন্ধযুক্ত পানি']].find(([term])=>lower.includes(term));matched=m?.[1]||''}voiceData.type=matched||'অন্য সমস্যা';if(!matched)voiceData.details=(voiceLanguage==='bn'?'অন্য সমস্যা: ':'Other problem: ')+answer}
  else if(voiceStep===3)voiceData.details+=(voiceData.details?'. ':'')+answer;
  else if(voiceStep===4){const lower=answer.toLocaleLowerCase(),yes=voiceLanguage==='bn'?/(হ্যাঁ|জরুরি|জি)/.test(lower):/\b(yes|urgent|yeah)\b/.test(lower),no=voiceLanguage==='bn'?/(না|নয়|নাহ)/.test(lower):/\b(no|not)\b/.test(lower);if(!yes&&!no){document.querySelector('#voiceFeedback').textContent=voiceLanguage==='bn'?'হ্যাঁ বা না বলুন।':'Please answer yes or no.';voiceQuestion();return}voiceData.urgent=yes}
  else if(voiceStep===5)voiceData.phone=answer;
  else if(voiceStep===6){const lower=answer.toLocaleLowerCase(),yes=voiceLanguage==='bn'?/(হ্যাঁ|জমা|ঠিক আছে|জি)/.test(lower):/\b(yes|submit|correct)\b/.test(lower),no=voiceLanguage==='bn'?/(না|বদল|ভুল)/.test(lower):/\b(no|change|incorrect)\b/.test(lower);if(yes){micReady=false;stopVoiceStream();voicePanel.hidden=true;choice.hidden=true;form.hidden=false;saveTicket(voiceData,voiceLanguage);voicePanel.hidden=false;form.hidden=true;document.querySelector('#voicePrompt').textContent=msg.textContent;document.querySelector('#voiceProgress').textContent=voiceLanguage==='bn'?'অভিযোগ জমা হয়েছে':'Report submitted';sayVoice(msg.textContent);return}if(no){micReady=false;stopVoiceStream();voicePanel.hidden=true;choice.hidden=false;form.hidden=false;form.elements.name.value=voiceData.name;form.elements.flat.value=voiceData.flat;form.elements.phone.value=voiceData.phone;form.elements.details.value=voiceData.details;msg.textContent=voiceLanguage==='bn'?'তথ্য ঠিক করে ফর্মটি জমা দিন।':'Please review the form, make changes, and submit it.';return}document.querySelector('#voiceFeedback').textContent=voiceLanguage==='bn'?'হ্যাঁ বা না বলুন।':'Please answer yes or no.';voiceQuestion();return}
  voiceStep++;voiceQuestion();
}
choice.querySelector('#typeWritten').onclick=()=>{voicePanel.hidden=true;form.hidden=false;choice.hidden=true;form.scrollIntoView({behavior:'smooth',block:'start'})};
choice.querySelector('#typeVoice').onclick=()=>{voicePanel.hidden=true;form.hidden=true;choice.hidden=true;recordPanel.hidden=false;captureStart.textContent='🎙 Start recording';captureTimer.textContent='';captureHelp.textContent='Starting the microphone. Speak in English when the timer appears.';recordPanel.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>captureStart.click(),250)};
async function beginVoiceSession(){
  voiceStep=0;voiceAttempts=0;micReady=false;voiceIntroStarting=true;voiceSpeechFailed=false;
  voiceLanguage='en';
  Object.assign(voiceData,{name:'',flat:'',type:'',details:'',urgent:false,phone:'',issue:''});
  voicePanel.dataset.started='true';
  document.querySelector('#voiceStart').hidden=true;document.querySelector('#voiceListen').hidden=true;document.querySelector('#voiceText').hidden=true;document.querySelector('#voiceSend').hidden=true;
  if(!recognitionClass||!navigator.mediaDevices?.getUserMedia){voiceIntroStarting=false;const notice='Voice input is unavailable here. Listen to the questions and type your answers.';showVoiceTyping(notice);sayVoice(notice,voiceQuestion);return}
  const intro=voiceLanguage==='bn'?'আচ্ছা, মাইক্রোফোন ব্যবহারের অনুমতি দিন। তারপর আমি একে একে প্রশ্ন করব; আপনি শুধু মুখে উত্তর দিন।':'Please allow microphone access. I will ask questions one at a time; just answer out loud.';
  let introFinished=false;
  sayVoice(intro,()=>{introFinished=true;if(micReady){voiceIntroStarting=false;voiceQuestion()}});
  try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true})}catch{voiceIntroStarting=false;const notice=voiceLanguage==='bn'?'মাইক্রোফোনের অনুমতি পাওয়া যায়নি। অনুমতি দিন, অথবা উত্তর লিখে দিন।':'Microphone access was not granted. Allow access or type your answers.';showVoiceTyping(notice);sayVoice(notice,voiceQuestion);return}
  recognition=new recognitionClass();recognition.lang=voiceLanguage==='bn'?'bn-BD':'en-US';recognition.continuous=false;recognition.interimResults=false;recognition.maxAlternatives=1;
  recognition.onresult=e=>{if(!voiceIntroStarting)acceptVoiceAnswer(e.results[0][0].transcript)};
  recognition.onerror=e=>{if(e.error==='not-allowed'||e.error==='service-not-allowed'){voiceIntroStarting=false;const notice=voiceLanguage==='bn'?'মাইক্রোফোনের অনুমতি পাওয়া যায়নি। উত্তর লিখে দিন।':'Microphone access failed. You can type your answers.';showVoiceTyping(notice);sayVoice(notice,voiceQuestion);return}if(voiceIntroStarting)return;voiceAttempts++;if(voiceAttempts>=2){const notice=voiceLanguage==='bn'?'উত্তর শোনা যাচ্ছে না। আপনি উত্তর লিখেও দিতে পারেন।':'I cannot hear you. You can type your answer instead.';showVoiceTyping(notice)}voiceQuestion()};
  micReady=true;
  if(introFinished){voiceIntroStarting=false;voiceQuestion()}
}
document.querySelector('#voiceStart').onclick=beginVoiceSession;
document.querySelector('#voiceSend').onclick=()=>{const input=document.querySelector('#voiceText');if(!input.value.trim()){document.querySelector('#voiceFeedback').textContent='Type an answer first.';return}const value=input.value;input.value='';acceptVoiceAnswer(value)};
document.querySelector('#voiceCancel').onclick=()=>{voicePanel.hidden=true;choice.hidden=false;form.hidden=true;document.querySelector('#voiceStart').hidden=false;micReady=false;stopVoiceStream();window.speechSynthesis?.cancel()};
