document.querySelector('#language').addEventListener('click',()=>{const englishMode=language==='en';choice.querySelector('h3').textContent=englishMode?'How would you like to report?':'কীভাবে অভিযোগ জানাবেন?';choice.querySelector('#typeWritten').textContent=englishMode?'Write a report':'লিখে অভিযোগ দিন';choice.querySelector('#typeVoice').textContent=englishMode?'🎙 Record a report':'🎙 রেকর্ড করে অভিযোগ দিন';voicePanel.querySelector('.voice-heading h3').textContent=englishMode?'Voice assistant':'কণ্ঠ সহায়ক';voicePanel.querySelector('.voice-heading p').textContent=englishMode?'It will ask one question at a time.':'শুরু করলে একবারে একটি করে প্রশ্ন করবে।';voicePanel.querySelector('#voiceStart').textContent=englishMode?'Start speaking':'কথা বলা শুরু করুন';voicePanel.querySelector('#voiceListen').textContent=englishMode?'Speak your answer':'উত্তর বলুন';voicePanel.querySelector('#voiceText').placeholder=englishMode?'Type your answer':'এখানে উত্তর লিখুন';voicePanel.querySelector('#voiceSend').textContent=englishMode?'Send answer':'উত্তর পাঠান';voicePanel.querySelector('#voiceCancel').textContent=englishMode?'Back to report options':'ফর্মে ফিরে যান';if(!voicePanel.hidden&&voicePanel.dataset.started==='true')voiceQuestion()});
loginPage.querySelector('#loginForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),account=admins.find(a=>a.username===f.get('username')&&a.pin===f.get('pin'));if(!account){loginPage.querySelector('#loginMsg').textContent='ব্যবহারকারীর নাম অথবা পিন ভুল হয়েছে।';return}activeAdmin=account.username;sessionStorage.setItem(sessionKey,activeAdmin);updateHeaderAuth();showView('admin');location.hash='admin'};
